    def _show_hot_stocks_result_popup(self, stocks):
        """弹窗显示爬取的热门股列表,右侧显示涨跌幅、资金流入流出、主力净量(正红负绿);可保存到txt、股票数据表。"""
        if not stocks:
            messagebox.showinfo("提示", "未爬取到任何股票", parent=self.root)
            return
        win = self._toplevel(self.root)
        win.title("爬取热门股 - 结果")
        win.geometry("780x520")
        win.transient(self.root)
        top = ttk.Frame(win, padding=10)
        top.pack(fill=tk.BOTH, expand=True)
        ttk.Label(top, text=f"共 {len(stocks)} 只股票(选股通 + 同花顺热榜,已去重)", font=("TkDefaultFont", 12, "bold")).pack(anchor="w")
        list_frame = ttk.Frame(top)
        list_frame.pack(fill=tk.BOTH, expand=True, pady=(8, 8))
        text_widget = tk.Text(list_frame, height=20, font=("Consolas", 12), wrap=tk.NONE)
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scroll_y = ttk.Scrollbar(list_frame, orient=tk.VERTICAL, command=text_widget.yview)
        scroll_y.pack(side=tk.RIGHT, fill=tk.Y)
        scroll_x = ttk.Scrollbar(list_frame, orient=tk.HORIZONTAL, command=text_widget.xview)
        scroll_x.pack(side=tk.BOTTOM, fill=tk.X)
        text_widget.config(yscrollcommand=scroll_y.set, xscrollcommand=scroll_x.set)
        text_widget.tag_configure("red", foreground="#c00")
        text_widget.tag_configure("green", foreground="#080")
        # 表头
        text_widget.insert(tk.END, "代码\t名称\t涨跌幅\t资金流入流出\t主力净量\n", "header")
        text_widget.tag_configure("header", font=("Consolas", 12, "bold"))
        def _fmt_pct(v):
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return "--"
            try:
                x = float(v)
                return f"{x:+.2f}%"
            except (TypeError, ValueError):
                return str(v) if v != "" else "--"
        def _fmt_flow(v):
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return "--"
            try:
                x = float(v)
                if abs(x) >= 1e8:
                    return f"{x/1e8:+.2f}亿"
                if abs(x) >= 1e4:
                    return f"{x/1e4:+.2f}万"
                return f"{x:+.0f}"
            except (TypeError, ValueError):
                return str(v) if v != "" else "--"
        def _tag(val):
            if val is None or (isinstance(val, float) and pd.isna(val)):
                return None
            try:
                x = float(val)
                return "red" if x > 0 else "green" if x < 0 else None
            except (TypeError, ValueError):
                return None
        for s in stocks:
            code = s.get('code', '') or ''
            name = s.get('name', '') or ''
            pct = s.get('涨跌幅')
            flow = s.get('资金流入')
            main_q = s.get('主力净量')
            text_widget.insert(tk.END, f"{code}\t{name}\t", "default")
            # 涨跌幅
            tag_pct = _tag(pct)
            text_widget.insert(tk.END, _fmt_pct(pct) + "\t", tag_pct or "default")
            # 资金流入
            tag_flow = _tag(flow)
            text_widget.insert(tk.END, _fmt_flow(flow) + "\t", tag_flow or "default")
            # 主力净量
            tag_main = _tag(main_q)
            text_widget.insert(tk.END, _fmt_pct(main_q) if main_q is not None else "--", tag_main or "default")
            text_widget.insert(tk.END, "\n", "default")
        btn_frame = ttk.Frame(top)
        btn_frame.pack(fill=tk.X)
        def copy_all_text():
            lines = ["代码\t名称\t涨跌幅\t资金流入流出\t主力净量"]
            for s in stocks:
                lines.append(f"{s.get('code', '')}\t{s.get('name', '')}\t{_fmt_pct(s.get('涨跌幅'))}\t{_fmt_flow(s.get('资金流入'))}\t{_fmt_pct(s.get('主力净量')) if s.get('主力净量') is not None else '--'}")
            text = "\n".join(lines)
            try:
                self.root.clipboard_clear()
                self.root.clipboard_append(text)
                messagebox.showinfo("已复制", "结果已复制到剪贴板,可直接粘贴为文字。", parent=win)
            except Exception as e:
                messagebox.showerror("错误", f"复制失败: {e}", parent=win)
        ttk.Button(btn_frame, text="复制全部", command=copy_all_text, width=12).pack(side=tk.LEFT, padx=(0, 8))
        def save_to_txt():
            path = tk.filedialog.asksaveasfilename(
                parent=win, title="保存到文本文件",
                defaultextension=".txt", filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
            )
            if not path:
                return
            try:
                with open(path, "w", encoding="utf-8") as f:
                    f.write("代码\t名称\t涨跌幅\t资金流入流出\t主力净量\n")
                    for s in stocks:
                        f.write(f"{s.get('code', '')}\t{s.get('name', '')}\t{_fmt_pct(s.get('涨跌幅'))}\t{_fmt_flow(s.get('资金流入'))}\t{_fmt_pct(s.get('主力净量')) if s.get('主力净量') is not None else '--'}\n")
                messagebox.showinfo("成功", f"已保存 {len(stocks)} 条到\n{path}", parent=win)
            except Exception as e:
                messagebox.showerror("错误", f"保存失败: {e}", parent=win)
        def save_to_db():
            today = datetime.now().strftime("%Y-%m-%d")
            saved = 0
            for s in stocks:
                code = s.get('code', '')
                name = s.get('name', '') or code
                if code and save_stock_to_db(code, name, today):
                    saved += 1
            messagebox.showinfo("成功", f"已保存 {saved} 条到股票数据表(stock_data),日期 {today}", parent=win)
        ttk.Button(btn_frame, text="保存到 TXT 文件", command=save_to_txt, width=16).pack(side=tk.LEFT, padx=(0, 8))
        ttk.Button(btn_frame, text="保存到股票数据表", command=save_to_db, width=18).pack(side=tk.LEFT, padx=(0, 8))
        ttk.Button(btn_frame, text="关闭", command=win.destroy, width=10).pack(side=tk.LEFT)
    @staticmethod
    def _enable_text_copy_menu(text_widget, readonly=True):
        """
        给任意 Text / ScrolledText 组件加上:
          1. 右键菜单(复制 / 全选 / 粘贴 / 剪切 / 清空)
          2. Cmd+A (macOS) / Ctrl+A (Win/Linux) 全选快捷键
          3. 拖拽选中 + 双击选词(Tk 自带)
        readonly=True 时只保留 复制/全选,禁用粘贴/剪切/清空
        """
        w = text_widget
        def _copy():
            try:
                sel = w.get("sel.first", "sel.last")
                if sel:
                    w.clipboard_clear()
                    w.clipboard_append(sel)
                    w.update()
            except tk.TclError:
                pass  # 没有选中
        def _select_all():
            w.tag_add("sel", "1.0", "end-1c")
            w.mark_set("insert", "1.0")
            w.see("insert")
        def _paste():
            if readonly:
                return
            try:
                clip = w.clipboard_get()
                if clip:
                    w.insert("insert", clip)
            except tk.TclError:
                pass
        def _cut():
            if readonly:
                return
            try:
                sel = w.get("sel.first", "sel.last")
                if sel:
                    w.clipboard_clear()
                    w.clipboard_append(sel)
                    w.delete("sel.first", "sel.last")
            except tk.TclError:
                pass
        def _clear():
            if readonly:
                return
            w.delete("1.0", tk.END)
        menu = tk.Menu(w, tearoff=0)
        menu.add_command(label="📋 复制 (⌘C)", command=_copy)
        menu.add_command(label="☑️ 全选 (⌘A)", command=_select_all)
        if not readonly:
            menu.add_separator()
            menu.add_command(label="✂️ 剪切 (⌘X)", command=_cut)
            menu.add_command(label="📌 粘贴 (⌘V)", command=_paste)
            menu.add_separator()
            menu.add_command(label="🗑️ 清空", command=_clear)
        def _show_menu(event):
            try:
                menu.tk_popup(event.x_root, event.y_root)
            finally:
                menu.grab_release()
        # macOS 右键是 Button-2,Windows/Linux 是 Button-3
        w.bind("<Button-2>", _show_menu)
        w.bind("<Button-3>", _show_menu)
        # 全选快捷键
        w.bind("<Command-a>", lambda e: (_select_all(), "break"))
        w.bind("<Control-a>", lambda e: (_select_all(), "break"))
        w.bind("<Command-A>", lambda e: (_select_all(), "break"))
        w.bind("<Control-A>", lambda e: (_select_all(), "break"))
        # 复制快捷键(Tk 默认只在 Entry/Spinbox 工作,Text 手动绑定更可靠)
        w.bind("<Command-c>", lambda e: (_copy(), "break"))
        w.bind("<Control-c>", lambda e: (_copy(), "break"))
        w.bind("<Command-C>", lambda e: (_copy(), "break"))
        w.bind("<Control-C>", lambda e: (_copy(), "break"))
        if not readonly:
            w.bind("<Command-v>", lambda e: (_paste(), "break"))
            w.bind("<Control-v>", lambda e: (_paste(), "break"))
            w.bind("<Command-x>", lambda e: (_cut(), "break"))
            w.bind("<Control-x>", lambda e: (_cut(), "break"))
        return w
    @staticmethod
    def _render_text_to_long_image(text, title="", bg_color="#FFFFFF",
                                    text_color="#212121", title_color="#333333",
                                    width_px=1080, font_size=16, line_height_factor=1.7):
        """把任意长文本渲染成长图 PNG（用 matplotlib，返回文件路径）。
        可设置背景色、标题、字体大小等。"""
        import matplotlib
        matplotlib.use("Agg")
        import os
        import tempfile

        import matplotlib.pyplot as plt
        from matplotlib.font_manager import FontProperties
        # --- 尝试找一个支持中文的字体 ---
        _cjk_fonts = [
            "/System/Library/Fonts/STHeiti Medium.ttc",
            "/System/Library/Fonts/Hiragino Sans GB.ttc",
            "/System/Library/Fonts/Supplemental/Songti.ttc",
            "/System/Library/Fonts/PingFang.ttc",
            "/Library/Fonts/Arial Unicode.ttf",
            "/System/Library/Fonts/Supplemental/Arial Unicode.ttf",
            # Windows fallback
            "C:/Windows/Fonts/msyh.ttc",
            "C:/Windows/Fonts/simhei.ttf",
        ]
        _font_path = None
        for _f in _cjk_fonts:
            if os.path.exists(_f):
                _font_path = _f
                break
        if _font_path:
            _fp = FontProperties(fname=_font_path, size=font_size)
            _title_fp = FontProperties(fname=_font_path, size=font_size + 4, weight="bold")
            _body_fp = _fp
        else:
            _fp = FontProperties(size=font_size)
            _title_fp = FontProperties(size=font_size + 4, weight="bold")
            _body_fp = _fp
        # --- 把文字按宽度换行（matplotlib 不自动换行） ---
        # 去掉 emoji（Heiti/PingFang 字体不含 emoji 字形）
        import re as _re
        _emoji_pattern = _re.compile(
            "[" "\U0001F000-\U0001FFFF" "\U00002600-\U000027BF"
            "\U0001F300-\U0001F5FF" "\U0001F600-\U0001F64F"
            "\U0001F680-\U0001F6FF" "\U0001F700-\U0001F77F"
            "\U0001F900-\U0001F9FF" "\U000025AA-\U000025FE"
            "\U0001FA00-\U0001FA6F" "\U0001FA70-\U0001FAFF" "]+",
            flags=_re.UNICODE)
        # 估算每个字符占的宽度（中文≈1个fontsize，英文≈0.55）
        char_w = font_size * 0.62
        max_chars_per_line = max(20, int((width_px - 100) / char_w))
        lines_raw = text.split("\n")
        wrapped = []
        for raw in lines_raw:
            # 处理 markdown 粗体 **text** — matplotlib 不支持，去掉 **
            raw_clean = raw.replace("**", "").replace("__", "")
            # 去掉 emoji
            raw_clean = _emoji_pattern.sub("", raw_clean).strip()
            if not raw_clean:
                wrapped.append("")
                continue
            if len(raw_clean) <= max_chars_per_line:
                wrapped.append(raw_clean)
            else:
                # 硬换行
                for j in range(0, len(raw_clean), max_chars_per_line):
                    wrapped.append(raw_clean[j:j + max_chars_per_line])
        # --- 计算图片尺寸（所有像素值 → 最后统一 / dpi 转英寸）---
        margin_top = 60
        margin_bottom = 40
        line_h = font_size * line_height_factor
        title_h = (font_size + 4) * 1.8 if title else 0
        content_h = len(wrapped) * line_h
        total_h_px = int(margin_top + title_h + content_h + margin_bottom + 20)
        # 最小 400px, 最大 6000px 防止 PIL DecompressionBomb
        total_h_px = max(400, min(6000, total_h_px))
        dpi = 100
        w_in = width_px / dpi
        h_in = total_h_px / dpi
        fig = plt.figure(figsize=(w_in, h_in), dpi=dpi)
        fig.patch.set_facecolor(bg_color)
        ax = fig.add_axes([0, 0, 1, 1])
        ax.axis("off")
        ax.set_facecolor(bg_color)
        # --- 画标题（坐标用 px，matplotlib 会自动按 dpi 映射）---
        y_cursor = total_h_px - margin_top
        if title:
            ax.text(width_px / 2 / dpi, y_cursor / dpi, title,
                    fontproperties=_title_fp, color=title_color,
                    ha="center", va="top")
            y_cursor -= title_h + 10
            # 分隔线
            ax.plot([60 / dpi, (width_px - 60) / dpi],
                    [(y_cursor - 4) / dpi, (y_cursor - 4) / dpi],
                    color="#CCCCCC", linewidth=1)
            y_cursor -= 20
        # --- 画正文 ---
        x_start = 60
        for line in wrapped:
            ax.text(x_start / dpi, y_cursor / dpi, line,
                    fontproperties=_body_fp, color=text_color,
                    ha="left", va="top")
            y_cursor -= line_h
            if y_cursor < 20:
                break
        # --- 保存 ---
        tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
        tmp.close()
        fig.savefig(tmp.name, dpi=dpi, bbox_inches="tight", pad_inches=0.1,
                    facecolor=bg_color, edgecolor="none")
        plt.close(fig)
        return tmp.name
    def _open_image_popup_with_save(self, text, title="创作结果",
                                     default_bg="#FFFFFF", default_text="#212121"):
        """双击文本框 → 弹出大图预览窗口，可换背景色、保存长图。"""
