    # ==================== 多标签页管理方法 ====================
    def create_text_tab(self, title, initial_text="", bg_color=None):
        """创建新的文本标签页
        Args:
            title: 标签页标题
            initial_text: 初始文本内容
            bg_color: 背景颜色(可选)
        """
        self.tab_counter += 1
        tab_id = f"tab_{self.tab_counter}"
        # 创建标签页框架
        tab_frame = ttk.Frame(self.text_notebook)
        # 缩短标签页名称(如果太长)
        display_title = title
        if len(title) > 15:
            display_title = title[:12] + "..."
        self.text_notebook.add(tab_frame, text=display_title)
        # 如果没有指定背景色,使用默认白色
        if bg_color is None:
            bg_color = 'white'
        # 根据情绪周期确定背景颜色(如果未指定)
        if bg_color is None or bg_color == 'white':
            if hasattr(self, 'get_emotion_bg_color'):
                bg_color = self.get_emotion_bg_color()
        # 创建文本框和滚动条(固定宽度,不随标签页变化)
        text_widget = tk.Text(tab_frame, height=15, width=45, font=("TkDefaultFont", 16),
                             wrap=tk.WORD, undo=True, maxundo=50, bg=bg_color)
        scrollbar = tk.Scrollbar(tab_frame, orient=tk.VERTICAL, command=text_widget.yview)
        text_widget.configure(yscrollcommand=scrollbar.set)
        # 配置颜色标签
        color_tags = [
            ("red", "red"), ("orange", "orange"), ("green", "green"),
            ("blue", "blue"), ("purple", "purple"), ("black", "black")
        ]
        for tag_name, color in color_tags:
            text_widget.tag_configure(tag_name, foreground=color)
        # 绑定事件
        text_widget.bind('<Control-v>', self.on_paste)
        text_widget.bind('<KeyRelease>', self.on_text_change)
        text_widget.bind('<Button-3>', self.show_context_menu)
        # 绑定双击事件,打开全窗口浏览
        text_widget.bind('<Double-Button-1>', lambda e, tid=tab_id: self.open_full_window_viewer(tid))
        # 布局
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        # 创建顶部工具栏(包含关闭按钮和图片插入按钮)
        toolbar = ttk.Frame(tab_frame)
        toolbar.pack(fill=tk.X, padx=2, pady=2, side=tk.TOP)
        # 如果是咨询标签页,添加图片插入按钮
        if title.startswith("咨询"):
            # 插入图片按钮
            insert_img_btn = ttk.Button(toolbar, text="📷 插入图片",
                                       command=lambda: self.insert_image_to_tab(tab_id))
            insert_img_btn.pack(side=tk.LEFT, padx=2)
            # 粘贴图片按钮
            paste_img_btn = ttk.Button(toolbar, text="📋 粘贴图片",
                                      command=lambda: self.paste_image_to_tab(tab_id))
            paste_img_btn.pack(side=tk.LEFT, padx=2)
        # 关闭按钮(使用×符号,更紧凑)
        close_btn = ttk.Button(toolbar, text="×", width=3,
                              command=lambda: self.close_tab(tab_id))
        close_btn.pack(side=tk.RIGHT, padx=2)
        # 插入初始文本
        if initial_text:
            # 如果文本包含图片标记,使用解析方法
            if "[IMAGE:" in initial_text:
                self.parse_and_display_images(text_widget, initial_text)
            else:
                text_widget.insert("1.0", initial_text)
        # 存储引用
        self.text_widgets[tab_id] = {
            'widget': text_widget,
            'title': title,
            'frame': tab_frame
        }
        # 切换到新标签页
        self.text_notebook.select(tab_frame)
        self.update_text_input_reference()
        return tab_id
    def get_image_save_directory(self):
        """获取图片保存目录(按日期组织)"""
        today = datetime.now().strftime("%Y-%m-%d")
        image_dir = os.path.join(D_IMAGES_DIR, today)
        os.makedirs(image_dir, exist_ok=True)
        return image_dir
    def save_image_file(self, image_path_or_data, is_file_path=True):
        """保存图片文件到日期目录
        Args:
            image_path_or_data: 图片文件路径或图片数据(PIL Image对象)
            is_file_path: True表示是文件路径,False表示是PIL Image对象
        Returns:
            保存的相对路径(相对于D_IMAGES_DIR)
        """
        try:
            image_dir = self.get_image_save_directory()
            today = datetime.now().strftime("%Y-%m-%d")
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            if is_file_path:
                # 从文件路径复制
                if not os.path.exists(image_path_or_data):
                    return None
                ext = os.path.splitext(image_path_or_data)[1] or '.png'
                filename = f"img_{timestamp}{ext}"
                dest_path = os.path.join(image_dir, filename)
                shutil.copy2(image_path_or_data, dest_path)
            else:
                # 从PIL Image对象保存
                filename = f"img_{timestamp}.png"
                dest_path = os.path.join(image_dir, filename)
                image_path_or_data.save(dest_path, 'PNG')
            # 返回相对路径(相对于D_IMAGES_DIR)
            relative_path = os.path.join(today, filename)
            return relative_path
        except Exception as e:
            messagebox.showerror("错误", f"保存图片失败: {e}")
            return None
    def insert_image_to_tab(self, tab_id):
        """在指定标签页插入图片"""
        try:
            if tab_id not in self.text_widgets:
                messagebox.showwarning("警告", "标签页不存在")
                return
            # 选择图片文件
            file_path = filedialog.askopenfilename(
                title="选择图片",
                filetypes=[
                    ("图片文件", "*.png *.jpg *.jpeg *.gif *.bmp *.ico"),
                    ("所有文件", "*.*")
                ]
            )
            if not file_path:
                return
            # 保存图片
            relative_path = self.save_image_file(file_path, is_file_path=True)
            if not relative_path:
                return
            # 在文本中插入图片标记
            text_widget = self.text_widgets[tab_id]['widget']
            cursor_pos = text_widget.index(tk.INSERT)
            # 插入图片标记
            image_marker = f"\n[IMAGE:{relative_path}]\n"
            text_widget.insert(cursor_pos, image_marker)
            # 配置图片标记的样式和点击事件
            start_pos = text_widget.index(f"{cursor_pos} linestart")
            end_pos = text_widget.index(f"{cursor_pos} lineend +1c")
            text_widget.tag_add("image_marker", start_pos, end_pos)
            text_widget.tag_config("image_marker", foreground="blue", underline=True)
            text_widget.tag_bind("image_marker", "<Button-1>",
                               lambda e, path=relative_path: self.view_image(path))
            messagebox.showinfo("成功", f"图片已插入: {relative_path}")
        except Exception as e:
            messagebox.showerror("错误", f"插入图片失败: {e}")
            import traceback
            traceback.print_exc()
    def paste_image_to_tab(self, tab_id):
        """从剪贴板粘贴图片到指定标签页"""
        try:
            if tab_id not in self.text_widgets:
                messagebox.showwarning("警告", "标签页不存在")
                return
            # 尝试从剪贴板获取图片
            try:
                # 尝试获取剪贴板中的图片
                clipboard_image = self.root.clipboard_get(type='image/png')
                # 如果成功,说明剪贴板中有图片数据
                # 但tkinter的clipboard_get不支持直接获取图片数据
                # 我们需要使用其他方法
            except:
                pass
            # 使用PIL从剪贴板读取图片
            try:
                from PIL import ImageGrab
                clipboard_image = ImageGrab.grabclipboard()
                if clipboard_image is None:
                    messagebox.showwarning("提示", "剪贴板中没有图片")
                    return
                # 保存图片
                relative_path = self.save_image_file(clipboard_image, is_file_path=False)
                if not relative_path:
                    return
                # 在文本中插入图片标记
                text_widget = self.text_widgets[tab_id]['widget']
                cursor_pos = text_widget.index(tk.INSERT)
                # 插入图片标记
                image_marker = f"\n[IMAGE:{relative_path}]\n"
                text_widget.insert(cursor_pos, image_marker)
                # 配置图片标记的样式和点击事件
                start_pos = text_widget.index(f"{cursor_pos} linestart")
                end_pos = text_widget.index(f"{cursor_pos} lineend +1c")
                text_widget.tag_add("image_marker", start_pos, end_pos)
                text_widget.tag_config("image_marker", foreground="blue", underline=True)
                text_widget.tag_bind("image_marker", "<Button-1>",
                                   lambda e, path=relative_path: self.view_image(path))
                messagebox.showinfo("成功", f"图片已粘贴: {relative_path}")
            except ImportError:
                messagebox.showerror("错误", "需要PIL库支持剪贴板图片功能")
            except Exception as e:
                messagebox.showerror("错误", f"粘贴图片失败: {e}")
                import traceback
                traceback.print_exc()
        except Exception as e:
            messagebox.showerror("错误", f"粘贴图片失败: {e}")
            import traceback
            traceback.print_exc()
    def view_image(self, relative_path):
        """查看图片"""
        try:
            full_path = os.path.join(D_IMAGES_DIR, relative_path)
            if not os.path.exists(full_path):
                messagebox.showerror("错误", f"图片文件不存在: {full_path}")
                return
            # 打开图片查看窗口
            image_window = self._toplevel(self.root)
            image_window.title(f"查看图片 - {os.path.basename(full_path)}")
            image_window.geometry("800x600")
            # 加载并显示图片
            try:
                img = Image.open(full_path)
                # 计算缩放比例以适应窗口
                max_width, max_height = 780, 580
                img_width, img_height = img.size
                scale = min(max_width / img_width, max_height / img_height, 1.0)
                new_width = int(img_width * scale)
                new_height = int(img_height * scale)
                img = img.resize((new_width, new_height), Image.Resampling.LANCZOS)
                photo = ImageTk.PhotoImage(img)
                # 创建标签显示图片
                img_label = tk.Label(image_window, image=photo)
                img_label.image = photo  # 保持引用
                img_label.pack(expand=True, fill=tk.BOTH, padx=10, pady=10)
                # 添加图片路径信息
                path_label = tk.Label(image_window, text=f"路径: {full_path}",
                                     font=("Arial", 9), fg="gray")
                path_label.pack(side=tk.BOTTOM, pady=5)
            except Exception as e:
                messagebox.showerror("错误", f"加载图片失败: {e}")
                image_window.destroy()
        except Exception as e:
            messagebox.showerror("错误", f"查看图片失败: {e}")
    def parse_and_display_images(self, text_widget, content):
        """解析文本中的图片标记并显示"""
        try:
            # 清空文本框
            text_widget.delete("1.0", tk.END)
            # 插入内容
            text_widget.insert("1.0", content)
            # 查找所有图片标记 [IMAGE:path]
            import re
            pattern = r'\[IMAGE:([^\]]+)\]'
            matches = list(re.finditer(pattern, content))
            # 为每个图片标记添加样式和点击事件
            for i, match in enumerate(matches):
                start_pos = f"1.0 + {match.start()}c"
                end_pos = f"1.0 + {match.end()}c"
                relative_path = match.group(1)
                # 为每个图片标记创建唯一的tag名称
                tag_name = f"image_marker_{i}"
                text_widget.tag_add(tag_name, start_pos, end_pos)
                text_widget.tag_config(tag_name, foreground="blue", underline=True)
                # 使用lambda的默认参数来捕获path值
                text_widget.tag_bind(tag_name, "<Button-1>",
                                   lambda e, path=relative_path: self.view_image(path))
        except Exception as e:
            print(f"解析图片标记失败: {e}")
            import traceback
            traceback.print_exc()
    def get_active_text_widget(self):
        """获取当前活动标签页的文本框"""
        try:
            selected_tab = self.text_notebook.select()
            if selected_tab:
                for tab_info in self.text_widgets.values():
                    if str(tab_info['frame']) == selected_tab:
                        return tab_info['widget']
        except:
            pass
        # 如果没有找到,返回第一个标签页
        if self.text_widgets:
            first_tab = next(iter(self.text_widgets.values()))
            return first_tab['widget']
        return None
    def get_current_text(self):
        """获取当前标签页的文本"""
        text_widget = self.get_active_text_widget()
        if text_widget:
            return text_widget.get("1.0", tk.END).strip()
        return ""
    def get_active_text_title(self):
        """获取当前活动左侧标签页的标题"""
        try:
            selected_tab = self.text_notebook.select()
            if selected_tab:
                for tab_info in self.text_widgets.values():
                    if str(tab_info['frame']) == selected_tab:
                        return tab_info['title']
        except Exception:
            pass
        # 回退:第一个标签页标题
        if self.text_widgets:
            first_tab = next(iter(self.text_widgets.values()))
            return first_tab.get('title', '未命名')
        return "未命名"
    def iter_text_widgets(self):
        """迭代所有标签页文本框"""
        for tab_info in self.text_widgets.values():
            yield tab_info['widget']
    def get_all_texts(self):
        """获取所有标签页文本"""
        all_texts = []
        for tab_id, tab_info in list(self.text_widgets.items()):  # 使用list()避免迭代时修改字典
            try:
                widget = tab_info.get('widget')
                if widget is None:
                    continue
                # 检查widget是否仍然存在
                if not hasattr(widget, 'winfo_exists') or not widget.winfo_exists():
                    continue
                text = widget.get("1.0", tk.END).strip()
                if text:
                    all_texts.append({
                        'title': tab_info.get('title', '未命名'),
                        'text': text
                    })
            except (tk.TclError, AttributeError) as e:
                # widget已被销毁或无效,跳过
                print(f"跳过无效的widget {tab_id}: {e}")
                continue
        return all_texts
    def update_text_input_reference(self):
        """更新text_input引用,指向当前活动标签页(保持向后兼容)"""
        self.text_input = self.get_active_text_widget()
    def _build_fish_phase_appendix_from_extracted_stocks(self, stock_items):
        """从 extract_stock_names 的结果列表生成「鱼身鱼尾」附录文本(规则同 _check_ma_status)。"""
        if not stock_items:
            return ""
        lines = []
        seen_codes = set()
        for item in stock_items:
            s = str(item).strip()
            if not s:
                continue
            display = s
            code6 = None
            m = re.match(r'^(\d{6})\s*\(', s)
            if m:
                code6 = m.group(1).zfill(6)
                if '(' in s and ')' in s:
                    display = s.split('(')[1].rstrip(')')
            elif '(' in s and ')' in s:
                display = s.split('(')[1].rstrip(')')
                c = get_stock_code_by_name(display)
                if c:
                    code6 = str(c)[-6:].zfill(6)
            else:
                c = get_stock_code_by_name(s)
                if c:
                    code6 = str(c)[-6:].zfill(6)
                display = s
            if not code6 or code6 in seen_codes:
                continue
            seen_codes.add(code6)
            try:
                ms = self._check_ma_status(code6)
                if ms.get('fish_body'):
                    tag = '鱼身'
                elif ms.get('fish_tail'):
                    tag = '鱼尾'
                else:
                    tag = '-'
                lines.append(f"{display}\t{tag}\n")
            except Exception:
                lines.append(f"{display}\t(检测失败)\n")
        if not lines:
            return ""
        return (
            "\n" + "=" * 80 + "\n"
            "【鱼身鱼尾】(站上10日且10/20日均线向上为鱼身;破10日或20日均线向下为鱼尾)\n"
            + "-" * 40 + "\n"
            + "".join(lines)
        )
