            ttk.Button(search_frame, text="下一个", command=search_next).pack(side=tk.LEFT, padx=2)
            ttk.Button(search_frame, text="上一个", command=search_prev).pack(side=tk.LEFT, padx=2)
            search_pos_label = ttk.Label(search_frame, text="")
