            ttk.Button(export_frame, text="📊 Excel", command=_do_export_excel).pack(side=tk.LEFT, padx=3)
            ttk.Button(export_frame, text="🖼️ 长图", command=_do_export_longimg).pack(side=tk.LEFT, padx=3)
