            result_text.bind("<Button-3>", _show_context_menu)
            # 配置文本标签 - 字号整体加大 2-4pt
            result_text.tag_configure("title", font=("PingFang SC", 16, "bold"), foreground="blue")
            result_text.tag_configure("section", font=("PingFang SC", 15, "bold"), foreground="green")
