            result_text.tag_configure("ma_near10_up", foreground="goldenrod")     # MA10/20 向上且价格靠近并高于 MA10(黄色)
            result_text.tag_configure("ma_near20_up", foreground="green")         # MA10/20 向上且价格靠近 MA20(绿色)
