        self._ia_score_canvas.pack(fill=tk.X)

        # 指数涨跌表格
        idx_frame = tk.LabelFrame(top, text="📈 实时指数涨跌", bg="#FAFAFA", font=("", 10, "bold"))
        idx_frame.pack(fill=tk.X, padx=10, pady=4)
