        _cal_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        grid_f = tk.Frame(_cal_canvas, bg="#1A1A2E")
        _cal_window_id = _cal_canvas.create_window((0, 0), window=grid_f, anchor="nw")
        # 让 grid_f 宽度跟随 canvas, 高度够了自动隐藏 scrollbar
