        def _bind_mousewheel(e):
            _cal_canvas.bind_all("<MouseWheel>", _on_mousewheel)
        def _unbind_mousewheel(e):
            _cal_canvas.unbind_all("<MouseWheel>")
        _cal_canvas.bind("<Enter>", _bind_mousewheel)
