    def _gather_ai_staff_analyst_context(self):
        """股票分析师:强制使用联网实时数据(不使用程序内旧缓存)并附界面状态。"""
        chunks = []
        now_ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        chunks.append(f"【实时联网市场上下文】采集时间:{now_ts}")
        chunks.append("(规则:优先 Tushare/问财/选股通/AKShare 实时链路,不读取旧缓存快照)\n")
        try:
            b = self._collect_quant_market_from_network()
            snap = b.get("snap")
            spot = b.get("spot") or {}
            concept_lines = b.get("concept_lines") or []
            errs = b.get("errors") or []
            chunks.append(
                self._compose_quant_dialog_right_text(
                    snap,
                    spot,
                    concept_lines,
                    network_time=now_ts,
                    network_errors=errs if errs else None,
                )
            )
        except Exception as e:
            chunks.append(f"实时联网拉取失败:{e}\n")
        chunks.append("\n【本程序主界面状态(仅作执行约束,不替代实时行情)】\n")
        try:
            chunks.append(
                f"情绪周期(同花顺三档):{self.ths_sentiment_trend_var.get()}\n"
                f"同花顺情绪指数 · 1日线往上:{self.sentiment_index_ma1_uptrend_var.get()}  "
                f"· 在1日线上:{self.sentiment_index_ma1_above_var.get()}\n"
            )
        except Exception:
            chunks.append("(无法读取界面变量)\n")
        return "\n".join(chunks)
    def _collect_holding_pool_stats(self):
        """左侧标签池:龙头股(2)≈情绪/龙头、15Min(3)≈技术面、Main(4)≈基本面/资讯;统计数量与代码重叠。"""
        out = {"labels": ("龙头股(情绪/龙头池)", "15Min(技术面池)", "Main(基本面/资讯池)"), "groups": (2, 3, 4)}
        def _codes_for(gi):
            hs, _, _, _ = self._get_holding_group_data(gi)
            codes = []
            for item in hs or []:
                if not item or not item[0]:
                    continue
                c = (item[1] or "").strip()
                if not c:
                    c = get_stock_code_by_name(item[0]) or ""
                c = c.zfill(6) if len(str(c)) <= 6 and str(c).isdigit() else ""
                if c:
                    codes.append(c)
            return codes
        c2, c3, c4 = _codes_for(2), _codes_for(3), _codes_for(4)
        s2, s3, s4 = set(c2), set(c3), set(c4)
        out["counts"] = (len(c2), len(c3), len(c4))
        out["triple_overlap_n"] = len(s2 & s3 & s4)
        out["pair_23"] = len(s2 & s3)
        out["pair_24"] = len(s2 & s4)
        out["pair_34"] = len(s3 & s4)
        out["fill_rates"] = tuple(round(n / 80.0, 4) for n in out["counts"])
        return out
    def _collect_shanghai_volatility_and_energy_text(self):
        """上证:近端波动率近似 + 能量学(聚集/发散)。"""
        lines = []
        lines.append("══ 上证指数 · 波动率与能量学(研判用)══")
        try:
            lines.append(self._compute_energy_analysis_report_text("000001", days=60))
        except Exception as e:
            lines.append(f"(能量学:{e})")
        try:
            import akshare as ak
            df = ak.index_zh_a_hist(symbol="000001", period="daily")
            if df is None or df.empty:
                lines.append("(日K不足,跳过波动率统计)")
            else:
                close_col = "收盘" if "收盘" in df.columns else None
                if not close_col:
                    for c in df.columns:
                        if "收盘" in str(c) or str(c).lower() == "close":
                            close_col = c
                            break
                if not close_col:
                    close_col = df.columns[-1]
                s = pd.to_numeric(df[close_col], errors="coerce").dropna()
                if len(s) >= 22:
                    r = s.pct_change().dropna()
                    tail = r.tail(20)
                    daily_std_pct = float(tail.std() * 100.0)
                    lines.append(
                        f"· 上证近20日收益波动(日收益率标准差):约 {daily_std_pct:.3f}%(越大表示短线波动越剧烈)"
                    )
                else:
                    lines.append("(有效样本不足)")
        except Exception as e:
            lines.append(f"(波动率统计失败:{e})")
        lines.append("")
        return "\n".join(lines)
