    def _gather_quant_emotion_context(self):
        """汇总与「仓位/情绪」相关的界面指标,供量化策略弹窗右侧展示。"""
        lines = []
        lines.append("══ 当前盘面与情绪相关指标(本窗口取值)══")
        lines.append("")
        def _g(varname, default="(无)"):
            v = getattr(self, varname, None)
            try:
                return v.get() if v is not None else default
            except Exception:
                return default
        lines.append(f"· 情绪周期(程序 1情绪周期): {_g('emotion_cycle_var')}")
        lines.append(f"· 同花顺三档(配置): {_g('ths_sentiment_trend_var')}")
        lines.append(
            f"· 同花顺情绪指数: 1日线往上={_g('sentiment_index_ma1_uptrend_var')}  "
            f"在1日线上={_g('sentiment_index_ma1_above_var')}  "
            f"已确认={_g('sentiment_index_check_var')}"
        )
        lines.append(f"· 三维打分(0-30 各): 基本面={_g('fundamental_var')}  技术面={_g('technical_var')}  情绪面={_g('sentiment_var')}")
        try:
            f, t, s = int(_g("fundamental_var", "0")), int(_g("technical_var", "0")), int(_g("sentiment_var", "0"))
            lines.append(f"· 三维总分: {f + t + s} / 90")
        except Exception:
            pass
        pv = getattr(self, "position_vars", None) or {}
        for key, label in (("emotion", "情绪天气"), ("v_judge", "大V"), ("yesterday", "昨日盘况")):
            vv = pv.get(key)
            try:
                lines.append(f"· {label}: {vv.get() if vv else '-'}")
            except Exception:
                lines.append(f"· {label}: -")
        lines.append(f"· 凯利相关·牌权: {_g('card_power_var')}  值搏率: {_g('value_risk_var')}")
        lines.append(f"· 主流板块: {_g('main_sector_var')}")
        lines.append(f"· 开新仓许可: {_g('new_position_var')}")
        lines.append(f"· 止损规则: {_g('stop_loss_var')}")
        try:
            lines.append(f"· 仓位演算结果: {pv.get('result').get()}")
        except Exception:
            pass
        try:
            lines.append(f"· 三维总分标签: {pv.get('total_score_var').get()}")
        except Exception:
            pass
        lines.append("")
        try:
            score = self._get_market_sentiment_score()
            lines.append(f"· 程序内大盘情绪分: {score}")
        except Exception:
            pass
        lines.append("")
        lines.append("(指标含义以软件内标签为准;量化组合为思路梳理,不构成投资建议。)")
        return "\n".join(lines)
    def _get_major_index_pct_from_tushare(self):
        """主要指数当日涨跌幅:Tushare `index_daily`(需 token;比东财现货接口更稳)。"""
        out = {}
        idx_map = {
            "上证指数": "000001.SH",
            "深证成指": "399001.SZ",
            "创业板指": "399006.SZ",
            "沪深300": "000300.SH",
            "中证500": "000905.SH",
            "科创50": "000688.SH",
            "中证1000": "000852.SH",
            "北证50": "899050.BJ",
        }
        if not TS_AVAILABLE or not (getattr(self, "ts_token", None) or TS_DEFAULT_TOKEN):
            return out
        end_date = datetime.now().strftime("%Y%m%d")
        start_date = (datetime.now() - timedelta(days=15)).strftime("%Y%m%d")
        try:
            self._ensure_tushare_client(self.ts_token or TS_DEFAULT_TOKEN)
            for cn, ts_code in idx_map.items():
                try:
                    df = self.ts_client.index_daily(ts_code=ts_code, start_date=start_date, end_date=end_date)
                    if df is None or df.empty:
                        continue
                    df = df.sort_values("trade_date").tail(2).reset_index(drop=True)
                    if len(df) < 2:
                        continue
                    prev_close = float(df.iloc[-2]["close"])
                    close = float(df.iloc[-1]["close"])
                    if prev_close <= 0:
                        continue
                    out[cn] = (close / prev_close - 1.0) * 100.0
                except Exception:
                    continue
        except Exception:
            pass
        return out
    def _get_major_index_pct_from_akshare(self):
        """东财指数现货涨跌幅:AKShare 补缺用。"""
        out = {}
        try:
            import akshare as ak
            df = ak.stock_zh_index_spot_em()
            if df is None or df.empty:
                return out
            name_col = "名称" if "名称" in df.columns else None
            pct_col = "涨跌幅" if "涨跌幅" in df.columns else None
            if not name_col or not pct_col:
                return out
            want = (
                "上证指数",
                "深证成指",
                "创业板指",
                "沪深300",
                "中证500",
                "科创50",
                "中证1000",
                "北证50",
            )
            for _, row in df.iterrows():
                nm = str(row.get(name_col, "")).strip()
                if nm not in want:
                    continue
                p = pd.to_numeric(row.get(pct_col), errors="coerce")
                if pd.notna(p):
                    out[nm] = float(p)
        except Exception:
            pass
        return out
    def _get_major_index_pct_dict(self):
        """指数涨跌幅:优先 Tushare 日线;缺项由东财指数现货 AKShare 补齐。"""
        out = dict(self._get_major_index_pct_from_tushare())
        for k, v in self._get_major_index_pct_from_akshare().items():
            if k not in out or out.get(k) is None:
                out[k] = v
        return out
    def _fetch_concept_board_leader_summary(self, top_n=18):
        """题材热度:优先同花顺概念 AKShare;失败则回退选股通主题库网页解析。"""
        import re
        lines = []
        keywords = (
            "人工智能",
            "AI",
            "券商",
            "证券",
            "半导体",
            "芯片",
            "新能源",
            "锂电池",
            "光伏",
            "机器人",
            "数字经济",
            "华为",
            "算力",
            "信创",
            "传媒",
            "游戏",
            "中特估",
            "红利",
        )
        hits = []
        err_ak = None
        try:
            import akshare as ak
            df = ak.stock_board_concept_name_ths()
            if df is None or df.empty:
                raise RuntimeError("AKShare 概念榜为空")
            pct_col = "涨跌幅" if "涨跌幅" in df.columns else None
            name_col = "板块名称" if "板块名称" in df.columns else ("名称" if "名称" in df.columns else df.columns[0])
            if pct_col is None:
                raise RuntimeError("无涨跌幅列")
            df = df.copy()
            df["_p"] = pd.to_numeric(df[pct_col], errors="coerce")
            df = df.dropna(subset=["_p"]).sort_values("_p", ascending=False)
            head = df.head(top_n)
            lines.append(f"══ 概念板块涨幅前 {top_n}(同花顺口径 · AKShare,可用时)══")
            for _, row in head.iterrows():
                nm = str(row.get(name_col, "")).strip()
                p = float(row["_p"])
                flag = " ★" if any(k in nm for k in keywords) else ""
                lines.append(f"  · {nm}: {p:+.2f}%{flag}")
                if any(k in nm for k in keywords):
                    hits.append((nm, p))
            strong = [h for h in hits if h[1] > 0]
            if strong:
                lines.append("")
                lines.append("keyword 命中(人工智能/券商/半导体等)涨势居前:" + ",".join(f"{a}({b:+.2f}%)" for a, b in strong[:12]))
            return lines, hits
        except Exception as e_ak:
            err_ak = str(e_ak)
        try:
            sectors = self._fetch_xuangutong_full_no_dedup() or []
            scored = []
            for s in sectors:
                nm = str(s.get("板块名", "")).strip()
                if not nm or nm.startswith("排序"):
                    continue
                raw = s.get("涨跌幅") or ""
                t = str(raw).strip().replace("%", "")
                m = re.search(r"[+-]?\d+\.?\d*", t)
                if not m:
                    continue
                try:
                    p = float(m.group(0))
                except ValueError:
                    continue
                scored.append((nm, p))
            scored.sort(key=lambda x: x[1], reverse=True)
            if not scored:
                raise RuntimeError("选股通未解析到有效板块")
            lines = []
            if err_ak:
                lines.append(f"(同花顺概念 AKShare 不可用:{err_ak})")
            lines.append(f"══ 主题板块涨幅前 {top_n}(选股通 zhutiku · 网页解析)══")
            hits = []
            for nm, p in scored[:top_n]:
                flag = " ★" if any(k in nm for k in keywords) else ""
                lines.append(f"  · {nm}: {p:+.2f}%{flag}")
                if any(k in nm for k in keywords):
                    hits.append((nm, p))
            strong = [h for h in hits if h[1] > 0]
            if strong:
                lines.append("")
                lines.append("keyword 命中涨势居前:" + ",".join(f"{a}({b:+.2f}%)" for a, b in strong[:12]))
            return lines, hits
        except Exception as e_xg:
            tail = err_ak or "AKShare 异常"
            return [f"(概念板块:AKShare「{tail}」;选股通「{e_xg}」)"], []
    def _format_sentiment_zone_snapshot_lines(self, snap):
        """将情绪区间快照格式化为只读文本(与右上「情绪总览」同源字段)。"""
        if not snap or not isinstance(snap, dict):
            return ["(本次联网未得到情绪五问快照:请检查网络、Node/pywencai(问财),或点击「完整刷新」重试。)"]
        lines = []
        t = snap.get("time", "")
        m = snap.get("metrics", {}) or {}
        def _fv(key, sub="value"):
            o = m.get(key)
            if isinstance(o, (int, float)):
                return float(o) if sub == "value" else None
            if not isinstance(o, dict):
                return None
            v = o.get(sub)
            if isinstance(v, (int, float)):
                return v
            return None
        lines.append(f"更新时间: {t}")
        v1 = _fv("m1_today")
        v1y = _fv("m1_yday")
        lines.append(
            f"问1 同花顺情绪指数:当日 {v1:+.2f}% / 昨日 {v1y:+.2f}%"
            if isinstance(v1, (int, float)) and isinstance(v1y, (int, float))
            else f"问1 同花顺情绪指数:当日/昨日涨跌幅(问财/日线回退,见数值) {v1} {v1y}"
        )
        mk = m.get("m2_market") or {}
        lines.append(
            f"问2 全A涨跌家数:上涨 {mk.get('up')} 下跌 {mk.get('down')} 平盘 {mk.get('flat')} 总计 {mk.get('total')}({mk.get('source', '')})"
        )
        lines.append(f"问3 60分钟上穿60日线且放量:约 { _fv('m3', 'count') } 只(问财条数)")
        lines.append(f"问4 15分钟多均线发散:约 { _fv('m4', 'count') } 只(问财条数)")
        hs, zz, kc = _fv("m5_hs300"), _fv("m5_zz500"), _fv("m5_kc30")
        av = _fv("m5_avg")
        def _fmt_pct_slot(v):
            if isinstance(v, (int, float)):
                return f"{v:+.2f}%"
            return "未获取"
        lines.append(
            f"问5 沪深300 {_fmt_pct_slot(hs)} · 中证500 {_fmt_pct_slot(zz)} · 科创30(问财名) {_fmt_pct_slot(kc)} · 三指均值 {_fmt_pct_slot(av)}"
        )
        return lines
    def _recommend_quant_strategies(self):
        """据当前情绪与三维分等给出择时/择股/仓位/风控的文字建议(规则化,可对照左侧 Skill)。"""
        try:
            cycle = self.emotion_cycle_var.get()
        except Exception:
            cycle = "震荡"
        try:
            ths = self.ths_sentiment_trend_var.get()
        except Exception:
            ths = "震荡"
        try:
            f, t, s = int(self.fundamental_var.get()), int(self.technical_var.get()), int(self.sentiment_var.get())
        except Exception:
            f, t, s = 20, 20, 20
        tot = f + t + s
        try:
            conf_ok = self.sentiment_index_ma1_uptrend_var.get() and self.sentiment_index_ma1_above_var.get()
        except Exception:
            conf_ok = False
        try:
            new_ok = self.new_position_var.get() == "可以开新仓"
        except Exception:
            new_ok = False
        parts = []
        parts.append("══ 与当前状态匹配度较高的量化组合(规则摘要)══\n")
        # 择时
        if cycle == "下行" or ths == "下行":
            parts.append("【择时】防守/空仓窗口:趋势策略关闭或极低仓位;以波动率与 ERP 监控为主,等待情绪周期修复。")
        elif cycle == "上行" and conf_ok:
            parts.append("【择时】趋势/情绪共振:可对照「趋势跟踪」「情绪周期择时」提高风险敞口;仍以破位为出场信号。")
        else:
            parts.append("【择时】震荡/过渡:侧重「波动率择时」与区间工具,避免单边满仓;可小步试错。")
        # 择股
        if cycle == "下行" or tot < 45:
            parts.append("【择股】防御:红利低波、质量因子为主;减少题材追高与小盘纯动量。")
        elif tot >= 65 and f >= t and f >= s:
            parts.append("【择股】基本面驱动:多因子偏价值/质量,叠加财报与行业景气过滤。")
        elif tot >= 65 and (t >= f or s >= f):
            parts.append("【择股】动量/龙头:行业轮动+相对强度;对齐当前「主流板块」。")
        else:
            parts.append("【择股】均衡:多因子打底,少量动量增强;控制单票波动。")
        # 仓位
        if not new_ok or cycle == "下行":
            parts.append("【仓位】禁开新仓或仅试错仓:凯利/目标波动率输出应贴近下限;金字塔只减仓不加。")
        elif cycle == "上行" and conf_ok:
            parts.append("【仓位】可阶梯加仓:半凯利或目标波动率约束内,用金字塔确认趋势。")
        else:
            parts.append("【仓位】中性风险预算:牌权/值搏率与仓位演算一致,避免情绪面单日打满。")
        # 风控
        parts.append("【风控】严格执行界面「是否止损」规则;下行周期叠加账户回撤熔断与行业集中度上限。")
        if not conf_ok and cycle != "下行":
            parts.append("(补充)同花顺 1 日线条件未齐:量化上视为「趋势未确认」,择时信号应降档。")
        parts.append("\n左侧点选具体 Skill 可查看适用场景与实现要点。")
        return "\n".join(parts)
    def _quant_board_structure_lines(self, snap, spot):
        """对比上证/创业板/沪深300/中证500/科创50 等强弱(东财即时为主,情绪快照问财三指为辅)。"""
        lines = ["══ 2 指数强弱与风格(上证 vs 中证 vs 创业板 等)══"]
        merged = {}
        if spot:
            for k in (
                "上证指数",
                "深证成指",
                "创业板指",
                "沪深300",
                "中证500",
                "科创50",
                "中证1000",
                "北证50",
            ):
                if k in spot and isinstance(spot[k], (int, float)):
                    merged[k] = float(spot[k])
        m = (snap or {}).get("metrics") or {}
        for label, key in (
            ("沪深300(情绪区·问财)", "m5_hs300"),
            ("中证500(情绪区·问财)", "m5_zz500"),
            ("科创30(情绪区·问财名)", "m5_kc30"),
        ):
            o = m.get(key) or {}
            v = o.get("value")
            if isinstance(v, (int, float)):
                merged[label] = float(v)
        if not merged:
            lines.append("(暂无指数涨跌幅,请检查网络或 AKShare)")
            return lines
        items = sorted(merged.items(), key=lambda x: x[1], reverse=True)
        lines.append("排序(涨幅高→低):")
        lines.append("  " + " · ".join(f"{a} {b:+.2f}%" for a, b in items))
        hi, lo = items[0], items[-1]
        lines.append(f"今日相对最强:{hi[0]}({hi[1]:+.2f}%);最弱:{lo[0]}({lo[1]:+.2f}%)。")
        sh = merged.get("上证指数")
        cyb = merged.get("创业板指")
        zz5 = merged.get("中证500")
        hs3 = merged.get("沪深300")
        kc = merged.get("科创50")
        if isinstance(sh, float) and isinstance(cyb, float):
            if cyb > sh + 0.25:
                lines.append("风格:创业板指明显强于上证 → 偏成长/赛道弹性、小票情绪往往更活跃。")
            elif sh > cyb + 0.25:
                lines.append("风格:上证强于创业板 → 偏蓝筹/权重、大盘与价值风格相对占优。")
            else:
                lines.append("风格:上证与创业板接近 → 大小盘分化不大或同涨同跌。")
        if isinstance(zz5, float) and isinstance(hs3, float) and zz5 > hs3 + 0.2:
            lines.append("中证500 相对 沪深300 更强 → 中盘/主题弹性可能优于大盘权重。")
        if isinstance(kc, float) and isinstance(sh, float) and kc > sh + 0.35:
            lines.append("科创50 显著强于上证 → 硬科技/科创板情绪偏热。")
        lines.append("(补充:可与右上「情绪区间」问5 的沪深300/中证500/科创30 对照。)")
        return lines
    def _quant_snapshot_good_bad_lines(self, snap):
        """根据右上情绪区间五问 + 涨跌家数,给出简短大盘好坏判别(规则化)。"""
        lines = ["══ 3 大盘好坏(仅依据右上情绪区间指标 + 涨跌比)══"]
        if not snap or not isinstance(snap, dict):
            lines.append("(无快照)")
            return lines
        m = snap.get("metrics") or {}
        mk = m.get("m2_market") or {}
        up, down = mk.get("up"), mk.get("down")
        tot = mk.get("total") or 0
        m1 = (m.get("m1_today") or {}).get("value")
        m5a = (m.get("m5_avg"))
        if isinstance(m5a, dict):
            m5a = m5a.get("value")
        verdict = []
        if isinstance(up, (int, float)) and isinstance(down, (int, float)) and (up + down) > 0:
            if up > down * 1.3:
                verdict.append("涨跌结构偏多(上涨家数明显多于下跌)。")
            elif down > up * 1.3:
                verdict.append("涨跌结构偏空(下跌家数明显多于上涨)。")
            else:
                verdict.append("涨跌家数接近,盘面结构中性。")
        if isinstance(m1, (int, float)):
            if m1 >= 0.8:
                verdict.append("同花顺情绪指数当日涨幅较大 → 短线情绪偏热。")
            elif m1 <= -0.8:
                verdict.append("同花顺情绪指数当日跌幅较大 → 短线情绪偏冷。")
            else:
                verdict.append("同花顺情绪指数当日波动温和。")
        if isinstance(m5a, (int, float)):
            if m5a >= 0.4:
                verdict.append("沪深300/中证500/科创30 均线性偏强。")
            elif m5a <= -0.4:
                verdict.append("上述宽基平均偏弱,注意回撤与仓位。")
        ratio_txt = ""
        if isinstance(up, (int, float)) and isinstance(down, (int, float)) and tot:
            ratio_txt = f"上涨/下跌:{int(up)}/{int(down)}(样本总计约 {int(tot)})。"
        lines.append(ratio_txt or "涨跌家数未获取。")
        lines.append("综合:" + (" ".join(verdict) if verdict else "指标不全,请点「完整刷新」重新联网拉取。"))
        lines.append("声明:以上为规则摘要,不构成投资建议。")
        return lines
    def _quant_market_network_sources_header(self):
        """量化弹窗右侧:大盘情绪所用网络数据源说明(便于对照实盘)。"""
        return [
            "┏━━━━━━━━ 量化参考 · 大盘情绪(以下为即时网络拉取,非界面缓存) ━━━━━━━━┓",
            "【数据获取源(优先级)】",
            "  · 主要指数涨跌幅 → Tushare Pro `index_daily`(已配置 token 时优先);缺项再用东财现货 · AKShare `stock_zh_index_spot_em`",
            "  · 全 A 涨跌家数 → AKShare `stock_zh_a_spot_em`;失败则 Tushare `daily` 按最近交易日统计",
            "  · 情绪五问中宽基/涨跌家数 → 问财 `pywencai` + 上述 Tushare 自动补缺",
            "  · 同花顺情绪指数、问财技术条件家数 → `pywencai`(需 Node);情绪指数还可回退 Tushare/AKShare 日线",
            "  · 题材/概念热度 → 同花顺概念 · AKShare `stock_board_concept_name_ths`;失败则选股通主题库网页解析",
            "(本地仅「仓位」标签与 Skill 建议取自主界面变量;其余大盘字段均以本次联网结果为准。)",
            "",
        ]
    def _collect_quant_market_from_network(self):
        """量化弹窗专用:统一从网络采集大盘情绪相关数据(供右侧全文)。"""
        bundle = {"snap": None, "spot": {}, "concept_lines": [], "errors": []}
        try:
            bundle["snap"] = self._collect_sentiment_zone_snapshot()
        except Exception as e:
            bundle["errors"].append(f"情绪区间/问财快照: {e}")
        try:
            bundle["spot"] = self._get_major_index_pct_dict() or {}
        except Exception as e:
            bundle["errors"].append(f"主要指数涨跌幅: {e}")
        try:
            cl, _ = self._fetch_concept_board_leader_summary(18)
            bundle["concept_lines"] = cl or []
        except Exception as e:
            bundle["concept_lines"] = [f"(概念板块获取失败:{e})"]
            bundle["errors"].append(f"概念板块: {e}")
        return bundle
    def _compose_quant_dialog_right_text(self, snap, spot, concept_lines, *, network_time=None, network_errors=None):
        """量化弹窗右侧全文:数据源说明 → 情绪五问(联网)→ 指数 → 板块 → 好坏 → 左栏仓位 → Skill 建议。"""
        chunks = []
        chunks.extend(self._quant_market_network_sources_header())
        ts = network_time or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        chunks.append(f"══ 本轮联网采集时间:{ts} ══\n")
        if network_errors:
            chunks.append("(部分接口异常:" + ";".join(network_errors) + ")\n")
        chunks.append("══ 1 情绪区间五问(每次打开/刷新均重新请求问财与东财,与右上展示字段一致但不同步于旧缓存)══\n")
        chunks.extend(self._format_sentiment_zone_snapshot_lines(snap))
        chunks.append("")
        chunks.extend(self._quant_board_structure_lines(snap, spot))
        chunks.append("")
        chunks.append("══ 题材/概念热度(AKShare 概念榜或选股通网页,可与问财交叉验证)══")
        if concept_lines:
            chunks.extend(concept_lines)
        else:
            chunks.append("(未拉取)")
        chunks.append("")
        chunks.extend(self._quant_snapshot_good_bad_lines(snap))
        chunks.append("")
        chunks.append("┏━━━━━━━━ 左侧「仓位」标签页补充状态 ━━━━━━━━┓\n")
        chunks.append(self._gather_quant_emotion_context())
        chunks.append("\n")
        chunks.append(self._recommend_quant_strategies())
        return "\n".join(chunks)
    def _configure_quant_dialog_right_tags(self, w):
        """量化弹窗右侧:A 股情绪色(涨/偏多红 #d32f2f,跌/偏空绿 #2e7d32),同「情绪区间」总览。"""
        try:
            w.tag_configure("up_bold", foreground="#d32f2f", font=("Microsoft YaHei UI", 11, "bold"))
            w.tag_configure("down_bold", foreground="#2e7d32", font=("Microsoft YaHei UI", 11, "bold"))
            w.tag_configure("neutral", foreground="#212121", font=("Microsoft YaHei UI", 11))
        except Exception:
            pass
    def _quant_dialog_insert_pct_value(self, w, v):
        """插入涨跌幅百分比(带红绿)。"""
        if not isinstance(v, (int, float)):
            w.insert(tk.END, "未获取", ("neutral",))
            return
        s = f"{float(v):+.2f}%"
        tag = "up_bold" if float(v) > 0 else ("down_bold" if float(v) < 0 else "neutral")
        w.insert(tk.END, s, (tag,))
    def _quant_dialog_insert_up_down_count(self, w, v, *, is_up):
        """上涨家数红、下跌家数绿(情绪好/坏与盘面习惯一致)。"""
        if v is None:
            w.insert(tk.END, "-", ("neutral",))
            return
        if not isinstance(v, (int, float)):
            w.insert(tk.END, str(v), ("neutral",))
            return
        w.insert(tk.END, str(int(v)), ("up_bold" if is_up else "down_bold",))
    def _quant_dialog_insert_line_scan_pcts(self, w, line, end_newline=True):
        """行内所有「数字%」按正负着色(用于指数行、概念行等)。"""
        import re
        if line is None:
            line = ""
        pos = 0
        for m in re.finditer(r"([+-]?\d+\.?\d*)%", line):
            w.insert(tk.END, line[pos : m.start()])
            try:
                val = float(m.group(1))
            except ValueError:
                w.insert(tk.END, m.group(0), ("neutral",))
            else:
                tag = "up_bold" if val > 0 else ("down_bold" if val < 0 else "neutral")
                w.insert(tk.END, m.group(0), (tag,))
            pos = m.end()
        w.insert(tk.END, line[pos:])
        if end_newline:
            w.insert(tk.END, "\n")
    def _fill_quant_dialog_right_text_colored(
        self, w, snap, spot, concept_lines, *, network_time=None, network_errors=None
    ):
        """右侧全文:结构同 _compose_quant_dialog_right_text,数值按情绪红绿着色。"""
        def _ok_line(s):
            if not s:
                return False
            bad_tokens = ("未获取", "暂无", "未拉取", "无快照", "失败", "异常", "指标不全")
            return not any(t in str(s) for t in bad_tokens)
        w.delete("1.0", tk.END)
        for ln in self._quant_market_network_sources_header():
            w.insert(tk.END, ln + "\n")
        ts = network_time if network_time else datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        w.insert(tk.END, f"══ 本轮联网采集时间:{ts} ══\n")
        w.insert(
            tk.END,
            "══ 1 情绪区间五问(每次打开/刷新均重新请求问财与东财,与右上展示字段一致但不同步于旧缓存)══\n",
        )
        if snap and isinstance(snap, dict):
            t = snap.get("time", "")
            m = snap.get("metrics", {}) or {}
            def _fv(key, sub="value"):
                o = m.get(key)
                if isinstance(o, (int, float)):
                    return float(o) if sub == "value" else None
                if not isinstance(o, dict):
                    return None
                v = o.get(sub)
                if isinstance(v, (int, float)):
                    return v
                return None
            w.insert(tk.END, f"更新时间: {t}\n", ("neutral",))
            v1, v1y = _fv("m1_today"), _fv("m1_yday")
            if isinstance(v1, (int, float)) and isinstance(v1y, (int, float)):
                w.insert(tk.END, "问1 同花顺情绪指数:", ("neutral",))
                w.insert(tk.END, "当日 ", ("neutral",))
                self._quant_dialog_insert_pct_value(w, v1)
                w.insert(tk.END, " / 昨日 ", ("neutral",))
                self._quant_dialog_insert_pct_value(w, v1y)
                w.insert(tk.END, "\n")
            mk = m.get("m2_market") if isinstance(m.get("m2_market"), dict) else {}
            if isinstance(mk.get("up"), (int, float)) and isinstance(mk.get("down"), (int, float)):
                w.insert(tk.END, "问2 全A涨跌家数:上涨 ", ("neutral",))
                self._quant_dialog_insert_up_down_count(w, mk.get("up"), is_up=True)
                w.insert(tk.END, " 下跌 ", ("neutral",))
                self._quant_dialog_insert_up_down_count(w, mk.get("down"), is_up=False)
                if mk.get("flat") is not None:
                    w.insert(tk.END, " 平盘 ", ("neutral",))
                    w.insert(tk.END, str(mk.get("flat")), ("neutral",))
                if mk.get("total") is not None:
                    w.insert(tk.END, " 总计 ", ("neutral",))
                    w.insert(tk.END, str(mk.get("total")), ("neutral",))
                src = mk.get("source", "")
                if src:
                    w.insert(tk.END, f"({src})", ("neutral",))
                w.insert(tk.END, "\n")
            c3, c4 = _fv("m3", "count"), _fv("m4", "count")
            if isinstance(c3, (int, float)):
                w.insert(tk.END, "问3 60分钟上穿60日线且放量:约 ", ("neutral",))
                w.insert(tk.END, str(c3), ("neutral",))
                w.insert(tk.END, " 只(问财条数)\n", ("neutral",))
            if isinstance(c4, (int, float)):
                w.insert(tk.END, "问4 15分钟多均线发散:约 ", ("neutral",))
                w.insert(tk.END, str(c4), ("neutral",))
                w.insert(tk.END, " 只(问财条数)\n", ("neutral",))
            hs, zz, kc, av = _fv("m5_hs300"), _fv("m5_zz500"), _fv("m5_kc30"), _fv("m5_avg")
            chunks = []
            if isinstance(hs, (int, float)):
                chunks.append(("沪深300 ", hs))
            if isinstance(zz, (int, float)):
                chunks.append(("中证500 ", zz))
            if isinstance(kc, (int, float)):
                chunks.append(("科创30(问财名) ", kc))
            if isinstance(av, (int, float)):
                chunks.append(("三指均值 ", av))
            if chunks:
                w.insert(tk.END, "问5 ", ("neutral",))
                for i, (nm, vv) in enumerate(chunks):
                    if i > 0:
                        w.insert(tk.END, " · ", ("neutral",))
                    w.insert(tk.END, nm, ("neutral",))
                    self._quant_dialog_insert_pct_value(w, vv)
                w.insert(tk.END, "\n")
        w.insert(tk.END, "\n", ("neutral",))
        for ln in self._quant_board_structure_lines(snap, spot):
            if _ok_line(ln):
                self._quant_dialog_insert_line_scan_pcts(w, ln, end_newline=True)
        w.insert(tk.END, "\n", ("neutral",))
        w.insert(tk.END, "══ 题材/概念热度(AKShare 概念榜或选股通网页,可与问财交叉验证)══\n", ("neutral",))
        if concept_lines:
            for ln in concept_lines:
                if _ok_line(ln):
                    self._quant_dialog_insert_line_scan_pcts(w, ln, end_newline=True)
        w.insert(tk.END, "\n", ("neutral",))
        for ln in self._quant_snapshot_good_bad_lines(snap):
            if _ok_line(ln):
                self._quant_dialog_insert_line_scan_pcts(w, ln, end_newline=True)
        w.insert(tk.END, "\n", ("neutral",))
        w.insert(tk.END, "┏━━━━━━━━ 左侧「仓位」标签页补充状态 ━━━━━━━━┓\n", ("neutral",))
        w.insert(tk.END, self._gather_quant_emotion_context(), ("neutral",))
        w.insert(tk.END, "\n\n", ("neutral",))
        w.insert(tk.END, self._recommend_quant_strategies(), ("neutral",))
    def _extract_quant_hot_concepts_from_lines(self, concept_lines, top_n=6):
        """从概念行中提取涨幅靠前题材名。"""
        import re
        out = []
        for ln in concept_lines or []:
            m = re.match(r"\s*·\s*([^::]+)\s*[::]\s*([+-]?\d+\.?\d*)%", str(ln))
            if not m:
                continue
            nm = m.group(1).strip()
            try:
                p = float(m.group(2))
            except ValueError:
                continue
            out.append((nm, p))
        out.sort(key=lambda x: x[1], reverse=True)
        return out[:top_n]
    def _compose_quant_skill_ai_advice(self, skill_item, snap, spot, concept_lines):
        """按当前 Skill 结合右上行情给出规则化 AI 建议。"""
        name = skill_item.get("title", "")
        cat = skill_item.get("cat", "")
        m = (snap or {}).get("metrics", {}) or {}
        m1 = (m.get("m1_today") or {}).get("value")
        m5 = m.get("m5_avg")
        if isinstance(m5, dict):
            m5 = m5.get("value")
        mk = m.get("m2_market") if isinstance(m.get("m2_market"), dict) else {}
        up, down = mk.get("up"), mk.get("down")
        strength = "中性"
        if isinstance(m1, (int, float)) and isinstance(m5, (int, float)):
            if m1 >= 0.6 and m5 >= 0.2:
                strength = "偏强"
            elif m1 <= -0.6 and m5 <= -0.2:
                strength = "偏弱"
        if isinstance(up, (int, float)) and isinstance(down, (int, float)) and up + down > 0:
            if up > down * 1.25:
                strength = "偏强"
            elif down > up * 1.25:
                strength = "偏弱"
        lines = [
            f"【当前 Skill】{cat} · {name}",
            f"盘面判断:{strength}(m1={m1},m5均值={m5},涨跌家数={up}/{down})",
            "",
        ]
        hot_concepts = self._extract_quant_hot_concepts_from_lines(concept_lines, top_n=6)
        if cat == "择时":
            if strength == "偏强":
                lines.append("择时结论:可执行顺势择时,优先右侧结构最强指数方向,采用分批上仓。")
                lines.append("执行要点:首次试仓 30%-40%,若午后结构不破坏再加到 50%-70%。")
            elif strength == "偏弱":
                lines.append("择时结论:防守为主,尽量等确认信号,不建议激进追涨。")
                lines.append("执行要点:仅保留观察仓或空仓,等待 m1 与 m5 同步修复。")
            else:
                lines.append("择时结论:震荡过渡,适合轻仓试错+严格止损。")
                lines.append("执行要点:仓位不超过 40%,先看结构再决定是否放大。")
        elif cat == "择股":
            lines.append("择股结论:结合右上结构优先选强势题材与强于指数的个股。")
            if hot_concepts:
                lines.append("优先题材(来自右上题材热度):")
                for nm, p in hot_concepts[:5]:
                    lines.append(f"  - {nm}({p:+.2f}%)")
            try:
                hot_stocks = self._fetch_ths_full_no_dedup() or []
            except Exception:
                hot_stocks = []
            picked = []
            for it in hot_stocks:
                code = str(it.get("股票代码", "")).strip()
                nm = str(it.get("股票名称", "")).strip()
                if code and nm:
                    picked.append(f"{nm}({code})")
                if len(picked) >= 8:
                    break
            if picked:
                lines.append("候选股票(热度样本,需二次核验基本面/公告/流动性):")
                lines.append("  " + ",".join(picked))
            else:
                lines.append("候选股票:未获取到热榜样本,请先点“完整刷新“再试。")
        elif cat == "仓位":
            if strength == "偏强":
                lines.append("仓位建议:50%~75%,分两到三笔递进,不建议一键满仓。")
            elif strength == "偏弱":
                lines.append("仓位建议:0%~25%,以防守和等待确认为主。")
            else:
                lines.append("仓位建议:25%~45%,保持机动性。")
            lines.append("风控补充:单票止损与账户回撤阈值需同时生效。")
        else:
            lines.append("风控建议:按“单票止损 + 账户回撤熔断 + 行业集中度上限“三层执行。")
            if strength == "偏弱":
                lines.append("当前偏弱,建议缩短持仓观察周期并降低单票暴露。")
        lines.append("")
        lines.append("说明:以上为规则化 AI 辅助,不构成投资建议。")
        return "\n".join(lines)
    def _compose_quant_all_skills_ai_advice(self, catalog, snap, spot, concept_lines):
        """一键按全部 Skill 输出依次建议。"""
        parts = ["【一键AI量化】基于右上最新盘面,按左侧 Skill 逐条给出建议", ""]
        for it in catalog or []:
            parts.append(self._compose_quant_skill_ai_advice(it, snap, spot, concept_lines))
            parts.append("\n" + ("-" * 66) + "\n")
        return "\n".join(parts)
