            lhb_blast_scrollbar = ttk.Scrollbar(lhb_blast_table_frame, orient=tk.VERTICAL, command=lhb_blast_tree.yview)
            lhb_blast_tree.configure(yscrollcommand=lhb_blast_scrollbar.set)
