                # 股票明细:每只显示 最近10日涨跌幅、资讯表逻辑、三类提示标记
                stock_detail_lines = []
                for s in stock_stats[:80]:
                    logic_list = news_logic_by_code.get(s["code"], [])
                    logic_str = " | ".join(x[:100] for x in logic_list[:2]) if logic_list else "-"
                    tags = []
                    if s["in_fall"]:
                        tags.append("连续下跌5~10日")
                    if s["in_near"]:
                        tags.append("回靠10/20日线")
