        # ===== PanedWindow 左右分栏 =====
        paned = ttk.PanedWindow(win, orient=tk.HORIZONTAL)
        paned.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 6))
        # ===== 左侧：国际贵金属走势 + AI研判 =====
        left_frame = ttk.LabelFrame(paned, text="🌍 国际贵金属走势 + AI研判", padding=6)
