                up = market.get("up", 0); down = market.get("down", 0)
                total = up + down
                if total == 0: total = 1
                half_w = (cx1 - cx0 - 20) // 2
                # 上涨 → 红(A股惯例!)
                c.create_rectangle(cx0 + 10 + half_w - int(half_w * up / total), 55, cx0 + 10 + half_w, 75,
                                   fill=_RED_UP_LIGHT, outline="")
