                # 下跌 → 绿(A股惯例!)
                c.create_rectangle(cx0 + 10 + half_w, 55, cx0 + 10 + half_w + int(half_w * down / total), 75,
                                   fill=_GREEN_DOWN_LIGHT, outline="")
                c.create_text(cx1 - 5, 65, anchor=tk.E, text=f"{down} 跌", font=("Microsoft YaHei", 9, "bold"), fill=_GREEN_DOWN)
                # 涨停 / 跌停 - 涨停红、跌停绿
